using System;
using System.IO;
using System.Runtime.Loader;
using Evergine.Framework;
using Evergine.Common.Graphics;

/*
 * This file has been generated by evergine_debug tool.
 * It will redirect the load of the Mathematics dll.
 * We need to do this because Bullet uses an old Mathematics version.
 * It will also enable shader debug info.
 */

namespace evergine_debug
{
	public static class EvergineDebug
	{
		private static bool _initialized = false;

		public static void Initialize()
		{
			if (_initialized) return;
			_initialized = true;

			AssemblyLoadContext.Default.Resolving += (context, asm) =>
			{
				if (asm.Name == "Evergine.Mathematics")
				{
					var assemblyName = asm.Name + ".dll";
					var localPath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, assemblyName);
					if (File.Exists(localPath))
					{
						return context.LoadFromAssemblyPath(localPath);
					}
				}

				return null;
            };

			var graphicsContext = Application.Current.Container.Resolve<GraphicsContext>();
			graphicsContext.EnableShaderDebugInfo = false;
		}
	}
}
